     * Map membership points onto the numeric membership level: 1 for 0-1 points, 2 for 2-3 points,
     * 3 for 4-5 points and 4 for 6 or more points.
     */
    default int membershipLevel(int points) {
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }

